query:
mutation userCreateUser ( $accountId:ID! $createUserInput:CreateUserInput!) {
	user ( accountId:$accountId ) {
		createUser ( input:$createUserInput  )  {
			user {
				id
				userId
				objectId
				onPremSid
				firstName
				lastName
				userPrincipalName
				displayName
				phone
				email
				department
				jobTitle
				userStatus
				creationDate
				lastModified
				importType
				userImportType
				directoryId
				hasRemoteAccessEligibility
				authInfo {
					authMethod
					authStatus
				}
				riskScore
			}
		}
	}	
}
